@startuml

class Organizer {
  + FirstName : string
  + LastName : string
  + Email : string
  + PostalAddress : string
  + PhoneNumber : string
  + Password : string
}

class Attendee {
  + FirstName : string
  + LastName : string
  + Email : string
  + Password : string
  + AttendanceStatus : string
}

class EventType {
  + Name : string
}

class Event {
  + Occasion : string
  + StartDateTime : datetime
  + EndDateTime : datetime
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
  + Status : string
  + AssignedToAttendee : boolean
}

class Invitation {
  + Status : string
}

class ItemToBring {
  + Name : string
}

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Organizer "0..*" -- "0..*" Attendee : invites
Attendee "0..*" -- "0..*" Event : attends

Event "1" -- "1" EventType
Event "1" -- "1" Location
Event "1" *-- "0..*" Task
Event "1" -- "0..*" Invitation
Invitation "1" -- "1" Attendee
Invitation "1" -- "1" Event

Attendee "0..1" -- "0..*" ItemToBring : brings
Task "0..1" -- "0..*" ItemToBring : involves

@enduml

